// Register the scroll-to-track implementation onto the passed handle; clear
// it on dispose / handle swap so a stale browser never answers a call.
useEffect(() {
  browserController?._scrollToTrack = scrollToTrack;
  return () => browserController?._scrollToTrack = null;
}, [browserController]);

edits.newText:
// Register imperative scroll + visibility probes onto the passed handle.
// Visibility is used by the parent to conditionally expose an accessible
// “jump to now-playing” affordance on Linux.
useEffect(() {
  if (browserController == null) return null;

  browserController!._scrollToTrack = scrollToTrack;

  bool? isTrackVisible(String path) {
    if (!scroll.hasClients) return null;

    final rowContext = rowKeys[path]?.currentContext;
    if (rowContext == null) return null;

    final rowBox = rowContext.findRenderObject();
    if (rowBox is! RenderBox || !rowBox.hasSize) return null;

    final viewportContext = scroll.position.context.storageContext;
    final viewportBox = viewportContext.findRenderObject();
    if (viewportBox is! RenderBox || !viewportBox.hasSize) return null;

    final rowRect = rowBox.localToGlobal(Offset.zero) & rowBox.size;
    final viewportRect =
        viewportBox.localToGlobal(Offset.zero) & viewportBox.size;

    return rowRect.overlaps(viewportRect);
  }

  browserController!._isTrackVisible = isTrackVisible;

  // Let the parent compute an initial visibility state after first
  // layout, without waiting for a scroll event.
  WidgetsBinding.instance.addPostFrameCallback((_) {
    if (context.mounted) {
      browserController!.visibilityTick.value++;
    }
  });

  return () {
    browserController!._scrollToTrack = null;
    browserController!._isTrackVisible = null;
  };
}, [browserController, scroll, rowKeys]);

